const D = { energy: .6, scale: 1, speed: 1, density: .5, mach: .62, hue: 120, x: .5, y: .5, style: 'bench', act: 'sweep', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- An exact Doppler field, solved analytically per pixel, drawn as FRINGES.
// For a source in uniform straight-line motion the wavefront through a point p is found by
// solving the retarded-time quadratic |q + v*a| = c*a  (q = p - source_now, a = age of the
// wavefront). That yields, for free: compressed fronts ahead / rarefied astern, the true
// Doppler factor for colour, and — once M > 1 — a genuine silent zone with a Mach cone
// tangent to every front. Rendered as fine mid-key interference fringes into a coarse
// buffer: no filled discs, no white blowout, no flicker. NO STROBE.
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), diag = Math.sqrt(width*width + height*height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style;
const EN = cl(P.energy,0,1), SC = cl(P.scale,.4,2.6), SP = cl(P.speed,.2,3), DN = cl(P.density,0,1);
const AL = cl(P.alpha,0,100)/100;

// ---- monotonic internal clock (K.t may jump backwards on a t0 reset) ----
if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;

// ---- coarse field buffer -------------------------------------------------
const BW = Math.max(360, Math.min(720, Math.round(width / 2.4))), BH = cl(Math.round(BW*height/Math.max(1,width)), 40, 720);
const NPX = BW*BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; S.gnd = null;
}

// ---- cached medium: toned ground + grain + graticule + vignette -----------
// (texture, never a flat fill — and mid-key, so the plate never washes out)
const gkey = BW+'x'+BH+'|'+sty+'|'+sd;
if (!S.gnd || S.gkey !== gkey) {
  S.gkey = gkey; S.gnd = new Float32Array(NPX*3);
  let b0, b1, b2, gAmt, grid;
  if (sty === 'blueprint')      { b0=.070; b1=.140; b2=.275; gAmt=.15; grid=.075; }
  else if (sty === 'chalk')     { b0=.150; b1=.158; b2=.172; gAmt=.30; grid=.030; }
  else if (sty === 'ink')       { b0=.560; b1=.535; b2=.480; gAmt=.20; grid=.020; }
  else if (sty === 'ironbow')   { b0=.100; b1=.085; b2=.150; gAmt=.18; grid=.028; }
  else                          { b0=.150; b1=.230; b2=.310; gAmt=.17; grid=.035; }  // bench slate
  const gn = S.gnd;
  for (let j=0;j<BH;j++) for (let i=0;i<BW;i++) {
    const nx = i/BW - .5, ny = j/BH - .5, rr = Math.sqrt(nx*nx + ny*ny);
    const vig = 1 - rr*rr*.72;
    let h = Math.sin((i*12.9898 + j*78.233 + sd*7.13)*43758.5453); h -= Math.floor(h);
    let h2 = Math.sin((i*39.3468 + j*11.135 + sd*2.71)*24634.6345); h2 -= Math.floor(h2);
    const gg = 1 + (h-.5)*gAmt + (h2-.5)*gAmt*.45;
    const gx = Math.abs(((i/BW*16) % 1) - .5), gy = Math.abs(((j/BH*9) % 1) - .5);
    const gl = (gx > .47 || gy > .47) ? grid : 0;
    const o = 3*(j*BW+i);
    gn[o]   = b0*vig*gg + gl*.75;
    gn[o+1] = b1*vig*gg + gl*.95;
    gn[o+2] = b2*vig*gg + gl*1.15;
  }
}

// ---- act: a multi-minute programme for the Mach number --------------------
let mach = P.mach;
if (P.act === 'sweep')      mach = P.mach*(.85 + Math.min(.62, (K.section||0)*.155));   // walks up through the barrier
else if (P.act === 'chase') mach = P.mach*(.80 + .50*Math.sin(T*.031+1.1) + .22*Math.sin(T*.0117));
mach = cl(mach, .04, 2.4);

// wave geometry: FINE fringes. spacing is a fixed fraction of the frame, so `scale` is a
// legible knob (few huge fronts <-> a dense thicket) and the wave speed follows from it.
const fringeSp = u*.026*SC;
const dTau = cl(1/Math.max(.12, K.cps*1.5), .5, 4);       // seconds between emissions
const c = fringeSp/dTau;                                   // wave speed, px/s
const maxAge = cl(diag*1.05/Math.max(1e-3, c), 6, 400);    // fronts reach right across the frame
const invMax = 1/maxAge;
const Lp = diag*.95;                                        // straight pass length

const nSrc = cl(2 + Math.round(DN*3), 2, 5);
if (!S.src || S.srcN !== nSrc || S.seedUsed !== sd) {
  S.seedUsed = sd; S.srcN = nSrc; S.src = [];
  for (let k=0;k<nSrc;k++) S.src.push({
    th: fr(k*3.1+1)*6.2831,                 // heading (fixed for the pass — the solve needs it straight)
    b:  (fr(k*3.1+2)-.5)*diag*.40,          // perpendicular offset from the focus
    mk: .55 + .75*fr(k*3.1+3),              // per-source Mach spread — a mixed-regime ensemble
    d:  (.18 + .64*fr(k*3.1+4))*Lp          // distance travelled along the pass (starts in frame)
  });
}

// integrate each source along its line; wrap over a very long pass with a long fade
const SX=[], SY=[], VX=[], VY=[], AK=[], MK=[], EV=[], VM=[];
const fx = P.x*width, fy = P.y*height;
for (let k=0;k<nSrc;k++) {
  const s = S.src[k];
  const mk = cl(mach*s.mk, .03, 2.6);
  const vm = mk*c;
  s.d += vm*dt*SP;
  if (s.d > Lp) s.d -= Lp; if (s.d < 0) s.d += Lp;
  const dx = Math.cos(s.th), dy = Math.sin(s.th);
  const px0 = fx - dx*Lp*.5 - dy*s.b, py0 = fy - dy*Lp*.5 + dx*s.b;
  SX[k] = px0 + dx*s.d; SY[k] = py0 + dy*s.d;
  VX[k] = dx*vm; VY[k] = dy*vm; VM[k] = vm; MK[k] = mk;
  AK[k] = vm*vm - c*c;
  const q = s.d/Lp;                          // ~30s crossfade at each end of a ~5 min pass
  EV[k] = cl(q/.10, 0, 1)*cl((1-q)/.10, 0, 1);
}

// ---- solve the field ------------------------------------------------------
const g = S.g; g.loadPixels(); const qp = g.pixels;
const gn = S.gnd;
const gain = .26 + EN*.30 + K.intensity*.05 + (A.rms||0)*.22;
const hueT = (P.hue - 120)/360;
const SXW = width/BW, SYH = height/BH;
const CAP = sty === 'ink' ? .93 : .80;      // nothing is ever allowed to reach pure white
for (let j=0;j<BH;j++) {
  const py = (j+.5)*SYH;
  for (let i=0;i<BW;i++) {
    const px = (i+.5)*SXW;
    let amp = 0, hacc = 0;
    for (let k=0;k<nSrc;k++) {
      const ev = EV[k]; if (ev < .004) continue;
      const qx = px - SX[k], qy = py - SY[k];
      const vx = VX[k], vy = VY[k], Ak = AK[k];
      const B = 2*(qx*vx + qy*vy), C = qx*qx + qy*qy;
      let a1 = -1, a2 = -1;
      if (Ak > 1e-4) {                        // supersonic: a trailing cone, silent outside it
        if (B >= 0) continue;
        const disc = B*B - 4*Ak*C; if (disc <= 0) continue;
        const sq = Math.sqrt(disc);
        a1 = (-B - sq)/(2*Ak); a2 = (-B + sq)/(2*Ak);
      } else if (Ak < -1e-4) {                // subsonic: exactly one wavefront through p
        const disc = B*B - 4*Ak*C; if (disc <= 0) continue;
        a1 = (-B - Math.sqrt(disc))/(2*Ak);
      } else {                                // M = 1, the barrier
        if (B >= -1e-6) continue;
        a1 = -C/B;
      }
      for (let r=0;r<2;r++) {
        const a = r ? a2 : a1;
        if (!(a > 1e-5) || a > maxAge) continue;
        let dec = 1 - a*invMax; if (dec <= 0) continue; dec *= .22 + .78*dec;
        const ph = (T - a)/dTau;
        let w = .5 + .5*Math.cos(ph*6.2831);
        const w2 = w*w; w = w2*w2*w;          // ^5 -> thin, numerous fringes
        const e = dec*ev*(r ? .62 : 1);
        amp += w*e;
        // true acoustic Doppler factor at this pixel: 1/(1 - M cos(theta))
        const nx = qx + vx*a, ny = qy + vy*a; // |n| = c*a, points emission -> p
        const dd = MK[k]*((nx*vx + ny*vy)/(c*a*VM[k] + 1e-6));
        hacc += (.5 + .5*(dd/(.35 + (dd < 0 ? -dd : dd))))*w*e;
      }
    }
    if (amp > 1.0) amp = 1.0;
    const hv = amp > 1e-5 ? hacc/amp : .5;
    const o3 = 3*(j*BW+i), o4 = 4*(j*BW+i);
    let r0 = gn[o3], g0 = gn[o3+1], b0 = gn[o3+2];
    const f = amp*gain;
    let fr0, fg0, fb0;
    if (sty === 'chalk') { fr0 = .96; fg0 = .93; fb0 = .84; }
    else if (sty === 'blueprint') { fr0 = .58; fg0 = .86; fb0 = .96; }
    else if (sty === 'ironbow') {
      const m = .22 + hv*.78;
      fr0 = cl(m*2.2, 0, 1); fg0 = cl(m*1.9 - .60, 0, 1); fb0 = cl(m*3.2 - 2.3, 0, 1) + cl(.50 - m*1.8, 0, .5);
    } else {                                   // bench / ink: read the colour off the Doppler factor
      const hh = hueT + hv*.60;
      fr0 = .30 + .70*(.5 + .5*Math.cos(6.2831*hh));
      fg0 = .30 + .70*(.5 + .5*Math.cos(6.2831*(hh - .33)));
      fb0 = .30 + .70*(.5 + .5*Math.cos(6.2831*(hh - .67)));
    }
    if (sty === 'ink') {                       // sumi: the fringes BITE the paper instead of lighting it
      const bite = cl(f*.85, 0, .82);
      r0 *= 1 - bite*(1 - fr0*.35); g0 *= 1 - bite*(1 - fg0*.35); b0 *= 1 - bite*(1 - fb0*.35);
    } else { r0 += fr0*f; g0 += fg0*f; b0 += fb0*f; }
    qp[o4]   = (r0 > CAP ? CAP : r0)*255;
    qp[o4+1] = (g0 > CAP ? CAP : g0)*255;
    qp[o4+2] = (b0 > CAP ? CAP : b0)*255;
    qp[o4+3] = 255;
  }
}
g.updatePixels();

// ---- composite + the crisp diagram layer ---------------------------------
push();
image(g, 0, 0, width, height);
const dim = sty === 'ink';
const lineH = sty === 'chalk' ? 42 : sty === 'blueprint' ? 195 : sty === 'ink' ? 24 : (P.hue + 186) % 360;
const lineS = sty === 'chalk' ? 7 : sty === 'ink' ? 40 : 24;
const lineB = dim ? 18 : 74;
strokeCap(ROUND);
for (let k=0;k<nSrc;k++) {
  const s = S.src[k], ev = EV[k]; if (ev < .01) continue;
  const dx = Math.cos(s.th), dy = Math.sin(s.th);
  const sx = SX[k], sy = SY[k], mk = MK[k];
  // the source's track: a thin instrument rule, low key
  noFill(); stroke(lineH, lineS, lineB, 16*ev*AL); strokeWeight(Math.max(.6, u*.0012));
  line(sx - dx*diag*.9, sy - dy*diag*.9, sx + dx*u*.16, sy + dy*u*.16);
  // Mach cone: exists only above the barrier, tangent to every front at asin(1/M)
  if (mk > 1.03) {
    const mu = Math.asin(cl(1/mk, 0, 1)), ang = Math.atan2(dy, dx);
    stroke(lineH, lineS, dim ? 16 : 78, (34 + 26*EN)*ev*AL);
    strokeWeight(Math.max(.7, u*.0022*(.6 + EN*.7)));
    for (let q=-1;q<=1;q+=2) {
      const a2 = ang + Math.PI + q*mu;
      line(sx, sy, sx + Math.cos(a2)*diag*.9, sy + Math.sin(a2)*diag*.9);
    }
  }
  // the source itself: a small ring + core. Deliberately mid-key — no shadowBlur, no blowout.
  const kick = 1 + K.pulse*.14 + (A.bass||0)*.16;
  const sr = u*.0085*(.7 + EN*.5)*kick;
  noFill(); stroke(lineH, lineS, dim ? 20 : 80, 70*ev*AL); strokeWeight(Math.max(.7, u*.0018));
  ellipse(sx, sy, sr*2.4, sr*2.4);
  noStroke(); fill(lineH, lineS*.7, dim ? 12 : 76, 82*ev*AL);
  ellipse(sx, sy, sr, sr);
}
noStroke();
if (P.alpha < 100) { fill(0, 0, 0, 100 - cl(P.alpha,0,100)); rect(0, 0, width, height); }
pop();
noFill();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
